"use server"
import { prisma } from "@/lib/db"
import { revalidatePath } from "next/cache"
import bcrypt from "bcryptjs"
import { auth } from "@/lib/auth"
import { logActivity } from "@/lib/audit"

async function getDefaultCampusId() {
  const campus = await prisma.campus.findFirst()
  if (!campus) {
    const c = await prisma.campus.create({ data: { campusCode: "MAIN", campusName: "Campus Chinh", status: "ACTIVE" } })
    return c.id
  }
  return campus.id
}

/** Tim campusId theo name hoac id */
async function resolveCampusId(value: string | null | undefined): Promise<string | null> {
  if (!value) return null
  const campus = await prisma.campus.findFirst({ where: { OR: [{ id: value }, { campusName: value }, { campusCode: value }] } })
  return campus?.id || null
}

/** Tim departmentId theo name (neu truyen string name) hoac lay chinh no neu la id */
async function resolveDepartmentId(value: string | null | undefined): Promise<string | null> {
  if (!value) return null
  const dept = await prisma.department.findFirst({ where: { OR: [{ id: value }, { name: value }], status: "ACTIVE" } })
  return dept?.id || null
}

/** Tim subjectId theo subjectName hoac id */
async function resolveSubjectId(value: string | null | undefined): Promise<string | null> {
  if (!value) return null
  const sub = await prisma.subject.findFirst({ where: { OR: [{ id: value }, { subjectName: value }], status: "ACTIVE" } })
  return sub?.id || null
}

/** Assign a Class as homeroom for a teacher (bidirectional sync) */
async function assignHomeroomClass(teacherId: string, classId: string | null) {
  if (classId) {
    await prisma.$executeRawUnsafe(
      `UPDATE Class SET homeroomTeacherId = NULL WHERE homeroomTeacherId = ?`,
      teacherId
    )
    await prisma.$executeRawUnsafe(
      `UPDATE Class SET homeroomTeacherId = ? WHERE id = ?`,
      teacherId, classId
    )
    const cls = await prisma.class.findUnique({ where: { id: classId }, select: { className: true } })
    const className = cls?.className || ""
    await prisma.$executeRawUnsafe(
      `UPDATE Teacher SET homeroomClass = ? WHERE id = ?`,
      className, teacherId
    )
  } else {
    await prisma.$executeRawUnsafe(
      `UPDATE Class SET homeroomTeacherId = NULL WHERE homeroomTeacherId = ?`,
      teacherId
    )
    await prisma.$executeRawUnsafe(
      `UPDATE Teacher SET homeroomClass = NULL WHERE id = ?`,
      teacherId
    )
  }
}

/** Dong bo UserCampusAssignment cho userId */
async function syncAdditionalCampuses(userId: string, additionalCampusIds: string[]) {
  // Delete all existing assignments for this user
  await prisma.userCampusAssignment.deleteMany({ where: { userId } });
  // Re-create with the new list (skip empty values and ensure uniqueness)
  const uniqueIds = Array.from(new Set(additionalCampusIds.filter(Boolean)));
  if (uniqueIds.length > 0) {
    await prisma.userCampusAssignment.createMany({
      data: uniqueIds.map(campusId => ({ userId, campusId }))
    });
  }
}

export async function createTeacherAction(data: any) {
  try {
    const session = await auth()
    if (!session || !session.user) return { success: false, error: "Unauthorized: Vui lòng đăng nhập" }
    const role = (session.user as any)?.role || ""
    const isAllowed = ["ADMIN", "ADMINISTRATOR", "SUPER_ADMIN", "GDCS", "GĐCS", "NS", "GIAO_VU", "GIAO_VU_CS"].includes(role)
    if (!isAllowed) return { success: false, error: "Bạn không có quyền thêm mới giáo viên" }

    const teacherCode = data.teacherCode?.replace(/-/g, '').trim().toUpperCase()
    if (!teacherCode) {
      return { success: false, error: "Mã GV không được để trống!" }
    }

    const teacherName = String(data.teacherName || "").trim()
    if (!teacherName || teacherName.length < 2) {
      return { success: false, error: "Họ và tên giáo viên không được để trống và phải có ít nhất 2 ký tự!" }
    }

    // Check if Teacher already exists with this code
    const existing = await prisma.teacher.findUnique({ where: { teacherCode } })
    if (existing) {
      return { success: false, error: "Mã GV đã tồn tại: " + teacherCode }
    }

    // Check if the user email (which is teacherCode) is already associated with another Teacher
    const existingUser = await prisma.user.findUnique({ 
      where: { email: teacherCode },
      include: { teacher: true }
    })
    if (existingUser?.teacher) {
      return { success: false, error: `Tài khoản/Mã GV '${teacherCode}' đã được liên kết với một giáo viên khác!` }
    }

    const campusId = data.campusId || await getDefaultCampusId()
    const hashedPassword = await bcrypt.hash(teacherCode, 10)
    let userId: string

    if (existingUser) {
      userId = existingUser.id
    } else {
      const user = await prisma.user.create({
        data: { fullName: teacherName, email: teacherCode, passwordHash: hashedPassword, role: "TEACHER", status: "ACTIVE" }
      })
      userId = user.id
    }

    const departmentId = await resolveDepartmentId(data.department)
    const mainSubjectId = await resolveSubjectId(data.mainSubject)

    const teacher = await prisma.teacher.create({
      data: {
        userId, teacherCode, teacherName: data.teacherName,
        homeroomClass: null, email: data.email || null, phone: data.phone || null,
        dateOfBirth: data.dateOfBirth ? new Date(data.dateOfBirth) : null,
        departmentId: departmentId,
        mainSubjectId: mainSubjectId,
        campusId, status: "ACTIVE", position: data.position || "GV",
        positions: Array.isArray(data.positions) ? JSON.stringify(data.positions) : (data.positions || null)
      }
    })

    await logActivity(
      session.user.id,
      session.user.email || "SYSTEM",
      "CREATE_TEACHER",
      "Teacher",
      teacher.id,
      null,
      { teacherCode, teacherName: data.teacherName, campusId }
    )

    // Sync department assignments
    let deptAssignments: Array<{ departmentId: string; position?: string; isPrimary?: boolean }> = [];
    if (Array.isArray(data.departmentAssignments) && data.departmentAssignments.length > 0) {
      deptAssignments = data.departmentAssignments;
    } else if (Array.isArray(data.departmentIds) && data.departmentIds.length > 0) {
      deptAssignments = data.departmentIds.map((did: string, idx: number) => ({ departmentId: did, position: data.position || "GV", isPrimary: idx === 0 }));
    } else if (departmentId) {
      deptAssignments = [{ departmentId: departmentId, position: data.position || "GV", isPrimary: true }];
    }
    await syncTeacherDepartments(teacher.id, deptAssignments, data.position || "GV");

    // Sync division assignments (TBP)
    if (Array.isArray(data.divisionCodes)) {
      await syncTeacherDivisions(teacher.id, data.divisionCodes);
    }

    if (data.homeroomClassId) {
      await assignHomeroomClass(teacher.id, data.homeroomClassId)
    }

    // Sync additional campuses (UserCampusAssignment)
    const additionalCampuses = Array.isArray(data.additionalCampusIds) ? data.additionalCampusIds : [];
    const allCampuses = Array.from(new Set([campusId, ...additionalCampuses])).filter(Boolean);
    await syncAdditionalCampuses(userId, allCampuses);

    revalidatePath("/admin/teachers")
    revalidatePath("/admin/classes")
    return { success: true }
  } catch (e: any) {
    return { success: false, error: e.message }
  }
}

export async function updateTeacherAction(data: any) {
  try {
    const session = await auth()
    if (!session || !session.user) return { success: false, error: "Unauthorized: Vui lòng đăng nhập" }
    const role = (session.user as any)?.role || ""
    const isAllowed = ["ADMIN", "ADMINISTRATOR", "SUPER_ADMIN", "GDCS", "GĐCS", "NS", "GIAO_VU", "GIAO_VU_CS"].includes(role)
    if (!isAllowed) return { success: false, error: "Bạn không có quyền cập nhật thông tin giáo viên" }

    const { id, teacherName, dateOfBirth, campusId } = data
    const updateData: any = {}
    if (teacherName !== undefined) {
      const cleanName = String(teacherName).trim()
      if (cleanName.length < 2) {
        return { success: false, error: "Họ và tên giáo viên phải có ít nhất 2 ký tự!" }
      }
      updateData.teacherName = cleanName
    }
    if (dateOfBirth !== undefined) updateData.dateOfBirth = dateOfBirth ? new Date(dateOfBirth) : null
    if (campusId !== undefined) updateData.campusId = campusId
    if (data.status !== undefined) updateData.status = data.status
    if (data.email !== undefined) updateData.email = data.email || null
    if (data.position !== undefined) updateData.position = data.position
    if (data.positions !== undefined) {
      updateData.positions = Array.isArray(data.positions) ? JSON.stringify(data.positions) : (data.positions || null)
    }

    if (data.teacherCode) {
      const cleanCode = String(data.teacherCode).replace(/-/g, '').trim().toUpperCase()
      if (cleanCode) {
        const conflict = await prisma.teacher.findUnique({ where: { teacherCode: cleanCode } })
        if (conflict && conflict.id !== id) {
          return { success: false, error: `Mã GV '${cleanCode}' đã tồn tại!` }
        }
        updateData.teacherCode = cleanCode
      }
    }

    if (data.department !== undefined) {
      updateData.departmentId = await resolveDepartmentId(data.department)
    }
    if (data.mainSubject !== undefined) {
      updateData.mainSubjectId = await resolveSubjectId(data.mainSubject)
    }

    const oldTeacher = await prisma.teacher.findUnique({ where: { id } })
    await prisma.teacher.update({ where: { id }, data: updateData })
    await logActivity(
      session.user.id,
      session.user.email || "SYSTEM",
      "UPDATE_TEACHER",
      "Teacher",
      id,
      oldTeacher,
      updateData
    )

    if (teacherName || data.status !== undefined || updateData.teacherCode) {
      const teacher = await prisma.teacher.findUnique({ where: { id } })
      if (teacher) {
        const userUpdate: any = {}
        if (teacherName) userUpdate.fullName = teacherName
        if (data.status !== undefined) userUpdate.status = data.status
        if (updateData.teacherCode) userUpdate.email = updateData.teacherCode
        await prisma.user.update({ where: { id: teacher.userId }, data: userUpdate }).catch(() => {})
      }
    }

    // Sync additional campuses if campusId or additionalCampusIds is modified
    if (data.additionalCampusIds !== undefined || campusId !== undefined) {
      const teacher = await prisma.teacher.findUnique({ where: { id } });
      if (teacher && teacher.userId) {
        const currentAdditional = data.additionalCampusIds !== undefined
          ? data.additionalCampusIds
          : (await prisma.userCampusAssignment.findMany({ where: { userId: teacher.userId } }))
          .map(a => a.campusId)
          .filter(cid => cid !== teacher.campusId); // remove old primary
        const allCampuses = Array.from(new Set([campusId !== undefined ? campusId : teacher.campusId, ...currentAdditional])).filter(Boolean);
        await syncAdditionalCampuses(teacher.userId, allCampuses);
      }
    }

    if (data.departmentAssignments !== undefined || data.departmentIds !== undefined || data.department !== undefined) {
      let deptAssignments: Array<{ departmentId: string; position?: string; isPrimary?: boolean }> = [];
      if (Array.isArray(data.departmentAssignments)) {
        deptAssignments = data.departmentAssignments;
      } else if (Array.isArray(data.departmentIds)) {
        deptAssignments = data.departmentIds.map((did: string, idx: number) => ({ departmentId: did, position: data.position || "GV", isPrimary: idx === 0 }));
      } else if (data.department) {
        const resolvedId = await resolveDepartmentId(data.department);
        if (resolvedId) deptAssignments = [{ departmentId: resolvedId, position: data.position || "GV", isPrimary: true }];
      }
      await syncTeacherDepartments(id, deptAssignments, data.position);
    }

    // Sync division assignments (TBP)
    if (data.divisionCodes !== undefined) {
      await syncTeacherDivisions(id, Array.isArray(data.divisionCodes) ? data.divisionCodes : []);
    }

    revalidatePath("/admin/teachers")
    return { success: true }
  } catch (e: any) {
    return { success: false, error: e.message }
  }
}

export async function deleteTeacherAction(id: string) {
  try {
    const session = await auth()
    if (!session || !session.user) return { success: false, error: "Unauthorized: Vui lòng đăng nhập" }
    const role = (session.user as any)?.role || ""
    const isAllowed = ["ADMIN", "ADMINISTRATOR", "SUPER_ADMIN"].includes(role)
    if (!isAllowed) return { success: false, error: "Chỉ Quản trị viên cấp cao mới có quyền xóa hồ sơ giáo viên" }

    const teacher = await prisma.teacher.findUnique({ where: { id } })
    if (!teacher) return { success: false, error: "Không tìm thấy giáo viên" }

    // Ràng buộc 1: Kiểm tra phân công giảng dạy
    const assignmentCount = await prisma.teachingAssignment.count({ where: { teacherId: id } })
    if (assignmentCount > 0) {
      return {
        success: false,
        error: `Không thể xóa giáo viên: Đang có ${assignmentCount} phân công giảng dạy liên kết. Vui lòng chuyển giao/hủy phân công hoặc đổi trạng thái sang INACTIVE.`
      }
    }

    // Ràng buộc 2: Kiểm tra tiết dự giờ chủ trì
    const slotCount = await prisma.observationSlot.count({ where: { teacherId: id } })
    if (slotCount > 0) {
      return {
        success: false,
        error: `Không thể xóa giáo viên: Đang có ${slotCount} tiết dự giờ do giáo viên chủ trì. Vui lòng hủy/xóa các tiết dự giờ này trước.`
      }
    }

    // Ràng buộc 3: Kiểm tra đăng ký dự giờ
    const regCount = await prisma.observationRegistration.count({ where: { teacherId: id } })
    if (regCount > 0) {
      return {
        success: false,
        error: `Không thể xóa giáo viên: Đang có ${regCount} đăng ký tham gia dự giờ.`
      }
    }

    await prisma.$executeRawUnsafe(`UPDATE Class SET homeroomTeacherId = NULL WHERE homeroomTeacherId = ?`, id)
    await prisma.teacher.delete({ where: { id } })
    await logActivity(
      session.user.id,
      session.user.email || "SYSTEM",
      "DELETE_TEACHER",
      "Teacher",
      id,
      teacher,
      null
    )
    if (teacher.userId) {
      await prisma.user.delete({ where: { id: teacher.userId } }).catch(() => {})
    }
    revalidatePath("/admin/teachers")
    revalidatePath("/admin/classes")
    return { success: true }
  } catch (e: any) {
    return { success: false, error: e.message }
  }
}

export async function importTeachersAction(rows: any[], academicYearId?: string) {
  const session = await auth()
  if (!session || !session.user) return { success: false, error: "Unauthorized: Vui lòng đăng nhập" }
  const role = (session.user as any)?.role || ""
  const isAllowed = ["ADMIN", "ADMINISTRATOR", "SUPER_ADMIN", "GDCS", "GĐCS", "NS"].includes(role)
  if (!isAllowed) return { success: false, error: "Bạn không có quyền nhập danh sách giáo viên" }

  const defaultCampusId = await getDefaultCampusId()
  let created = 0, skipped = 0
  const errors: string[] = []
  const warnings: string[] = []
  const seenCodesInFile = new Set()

  // 1. Pre-fetch lookups to avoid O(N) database queries inside the loop
  const [campuses, departments, subjects] = await Promise.all([
    prisma.campus.findMany(),
    prisma.department.findMany({ where: { status: "ACTIVE" } }),
    prisma.subject.findMany({ where: { status: "ACTIVE" } })
  ])

  // Helper Maps for O(1) in-memory lookups
  const campusMap = new Map()
  campuses.forEach(c => {
    campusMap.set(c.id, c.id)
    campusMap.set(c.campusName, c.id)
    campusMap.set(c.campusCode, c.id)
  })

  const deptMap = new Map()
  departments.forEach(d => {
    deptMap.set(d.id, d.id)
    deptMap.set(d.name, d.id)
  })

  const subMap = new Map()
  subjects.forEach(s => {
    subMap.set(s.id, s.id)
    subMap.set(s.subjectName, s.id)
  })

  // 2. Pre-hash all teacherCodes in parallel to yield the single-threaded CPU loop periodically
  const hashedPasswordsMap = new Map()
  await Promise.all(
    rows.map(async (row) => {
      if (row.teacherCode) {
        const code = String(row.teacherCode).replace(/-/g, '').trim().toUpperCase()
        const hash = await bcrypt.hash(code, 10)
        hashedPasswordsMap.set(code, hash)
      }
    })
  )

  // 3. Process database updates sequentially
  for (const row of rows) {
    if (!row.teacherCode || !row.teacherName) { skipped++; continue }
    const code = String(row.teacherCode).replace(/-/g, '').trim().toUpperCase()
    if (seenCodesInFile.has(code)) {
      skipped++
      warnings.push(`Mã GV trùng lặp trong tệp Excel: ${code}`)
      continue
    }
    seenCodesInFile.add(code)

    try {
      const existing = await prisma.teacher.findUnique({ where: { teacherCode: code } })
      if (existing) {
        skipped++
        warnings.push(`Mã GV đã tồn tại trong hệ thống: ${code}`)
        continue
      }

      const hashedPassword = hashedPasswordsMap.get(code) || await bcrypt.hash(code, 10)
      const existingUser = await prisma.user.findUnique({ where: { email: code } })
      let userId: string
      if (existingUser) {
        userId = existingUser.id
      } else {
        const user = await prisma.user.create({
          data: { fullName: row.teacherName, email: code, passwordHash: hashedPassword, role: "TEACHER", status: "ACTIVE" }
        })
        userId = user.id
      }

      const departmentId = row.department ? (deptMap.get(row.department) || null) : null
      const mainSubjectId = row.mainSubject ? (subMap.get(row.mainSubject) || null) : null
      
      let campusId = defaultCampusId;
      const additionalCampusIds = [];

      if (row.campus) {
        const campusParts = typeof row.campus === "string"
          ? row.campus.split(/[,;|]/).map((s: string) => s.trim())
          : [row.campus];
        
        const primaryResolved = campusMap.get(campusParts[0]);
        if (primaryResolved) campusId = primaryResolved;

        for (let i = 1; i < campusParts.length; i++) {
          const cid = campusMap.get(campusParts[i]);
          if (cid) additionalCampusIds.push(cid);
        }
      }

      const teacher = await prisma.teacher.create({
        data: {
          userId, teacherCode: code, teacherName: row.teacherName,
          email: row.email || null, phone: row.phone || null,
          departmentId, mainSubjectId,
          campusId, status: "ACTIVE"
        }
      })

      // Sync additional campuses (UserCampusAssignment)
      const allCampuses = Array.from(new Set([campusId, ...additionalCampusIds])).filter(Boolean);
      await syncAdditionalCampuses(userId, allCampuses);

      if (row.homeroomClass) {
        const matchedClass = await prisma.class.findFirst({
          where: { className: { equals: row.homeroomClass } }
        })
        if (matchedClass) {
          await assignHomeroomClass(teacher.id, matchedClass.id)
        } else {
          await prisma.$executeRawUnsafe(`UPDATE Teacher SET homeroomClass = ? WHERE id = ?`, row.homeroomClass, teacher.id)
        }
      }
      created++
    } catch(e: any) {
      errors.push(code + ": " + e.message)
    }
  }

  await logActivity(
    session.user.id,
    session.user.email || "SYSTEM",
    "IMPORT_TEACHERS",
    "Teacher",
    "BATCH",
    null,
    { created, skipped, errorsCount: errors.length }
  )
  revalidatePath("/admin/teachers")
  revalidatePath("/admin/classes")
  return { success: true, created, skipped, errors, warnings }
}

export async function resetTeacherPasswordAction(teacherId: string) {
  try {
    const session = await auth()
    if (!session || !session.user) return { success: false, error: "Unauthorized: Vui lòng đăng nhập" }
    const role = (session.user as any)?.role || ""
    const isAllowed = ["ADMIN", "ADMINISTRATOR", "SUPER_ADMIN", "GDCS", "GĐCS"].includes(role)
    if (!isAllowed) return { success: false, error: "Bạn không có quyền đặt lại mật khẩu giáo viên" }

    const teacher = await prisma.teacher.findUnique({ where: { id: teacherId } })
    if (!teacher) return { success: false, error: "Không tìm thấy giáo viên" }
    const hashedPassword = await bcrypt.hash(teacher.teacherCode, 10)
    await prisma.user.update({ where: { id: teacher.userId }, data: { passwordHash: hashedPassword } })
    return { success: true }
  } catch (e: any) {
    return { success: false, error: e.message }
  }
}

export async function assignTeachersToRoleAction(teacherIds: string[], roleCode: string) {
  try {
    const session = await auth()
    if (!session || !session.user) return { success: false, error: "Unauthorized: Vui lòng đăng nhập" }
    const role = (session.user as any)?.role || ""
    const isAllowed = ["ADMIN", "ADMINISTRATOR", "SUPER_ADMIN"].includes(role)
    if (!isAllowed) return { success: false, error: "Bạn không có quyền phân quyền hàng loạt" }

    const teachers = await prisma.teacher.findMany({
      where: { id: { in: teacherIds } },
      select: { id: true, userId: true, teacherCode: true, teacherName: true, campusId: true }
    });

    const defaultCampus = await prisma.campus.findFirst();
    const defaultCampusId = defaultCampus?.id;

    for (const t of teachers) {
      if (t.userId) {
        // Update existing user role
        await prisma.user.update({
          where: { id: t.userId },
          data: { role: roleCode }
        });
      } else {
        // Create user record if missing (safeguard)
        const hashedPassword = await bcrypt.hash(t.teacherCode, 10);
        const newUser = await prisma.user.create({
          data: {
            fullName: t.teacherName,
            email: t.teacherCode,
            passwordHash: hashedPassword,
            role: roleCode,
            status: "ACTIVE"
          }
        });
        await prisma.teacher.update({
          where: { id: t.id },
          data: { userId: newUser.id }
        });
        
        // Also assign primary campus
        const campusId = t.campusId || defaultCampusId;
        if (campusId) {
          await prisma.userCampusAssignment.create({
            data: { userId: newUser.id, campusId }
          }).catch(() => {});
        }
      }
    }

    revalidatePath("/admin/teachers");
    revalidatePath("/admin/users");
    return { success: true };
  } catch (e: any) {
    return { success: false, error: e.message };
  }
}


/** Dong bo TeacherDepartmentAssignment cho teacherId */
export async function syncTeacherDepartments(
  teacherId: string,
  assignments: Array<{ departmentId: string; position?: string; isPrimary?: boolean }>,
  explicitPosition?: string
) {
  await prisma.teacherDepartmentAssignment.deleteMany({ where: { teacherId } });

  if (!assignments || assignments.length === 0) {
    const updateData: any = { departmentId: null };
    if (explicitPosition !== undefined) {
      updateData.position = explicitPosition;
    }
    await prisma.teacher.update({ where: { id: teacherId }, data: updateData });
    return;
  }

  const map = new Map<string, { departmentId: string; position: string; isPrimary: boolean }>();
  assignments.forEach((a, index) => {
    if (a.departmentId && !map.has(a.departmentId)) {
      map.set(a.departmentId, {
        departmentId: a.departmentId,
        position: a.position || "GV",
        isPrimary: a.isPrimary || index === 0
      });
    }
  });

  const uniqueAssignments = Array.from(map.values());
  if (uniqueAssignments.length > 0) {
    if (!uniqueAssignments.some(u => u.isPrimary)) {
      uniqueAssignments[0].isPrimary = true;
    }

    await prisma.teacherDepartmentAssignment.createMany({
      data: uniqueAssignments.map(u => ({
        teacherId,
        departmentId: u.departmentId,
        position: u.position,
        isPrimary: u.isPrimary
      }))
    });

    const primary = uniqueAssignments.find(u => u.isPrimary) || uniqueAssignments[0];
    
    let finalPosition = explicitPosition;
    if (!finalPosition) {
      const topPos = uniqueAssignments.find(u => u.position && u.position !== "GV")?.position;
      finalPosition = topPos || primary.position || "GV";
    }

    await prisma.teacher.update({
      where: { id: teacherId },
      data: {
        departmentId: primary.departmentId,
        position: finalPosition
      }
    });
  }
}

/** Đồng bộ TeacherDivisionAssignment cho teacherId (TBP) */
export async function syncTeacherDivisions(teacherId: string, divisionCodes: string[]) {
  const pAny = prisma as any;
  if (!pAny.teacherDivisionAssignment) return;
  await pAny.teacherDivisionAssignment.deleteMany({ where: { teacherId } });
  if (Array.isArray(divisionCodes) && divisionCodes.length > 0) {
    const validCodes = Array.from(new Set(divisionCodes.filter(Boolean)));
    if (validCodes.length > 0) {
      await pAny.teacherDivisionAssignment.createMany({
        data: validCodes.map(code => ({
          teacherId,
          divisionCode: code,
          roleInDivision: "TBP"
        }))
      });
    }
  }
}

